package org.example.spotifymixer.engine;

import org.example.spotifymixer.runtime.CreatorSession;import org.junit.Test;import static org.junit.Assert.*;import java.util.*;import java.util.function.Consumer;import java.io.IOException;
public class CreatorSessionTest {
 private static CreatorSession.Track t(int n){return new CreatorSession.Track("spotify:track:"+String.format(Locale.ROOT,"%022d",n),"Fixture track "+n,"Fixture artist");}
 private static CreatorSession.Request request(int n){return new CreatorSession.Request(" Evening "," rock ","","",n);}
 private static class Backend implements CreatorSession.Backend {
  List<CreatorSession.Track> tracks=new ArrayList<>(Arrays.asList(t(1),t(2),t(3)));int writes;boolean fail,wrong;List<CreatorSession.Track> written;String operation;
  public List<CreatorSession.Track> suggest(CreatorSession.Request r,Consumer<String> p){p.accept("Fixture suggestions");return tracks;}
  public CreatorSession.Receipt create(String name,List<CreatorSession.Track> tracks,String id)throws Exception{writes++;written=tracks;operation=id;if(fail)throw new IOException("Fixture timeout");return new CreatorSession.Receipt("spotify:playlist:0000000000000000000001",wrong?"Wrong name":name,tracks.size());}
 }
 @Test public void validatesPreferencesNameAndCount(){assertEquals("SpotEnhancer-Evening",request(3).playlistName());assertEquals("rock",request(1).genres);for(int n:new int[]{0,-1,501})try{request(n);fail();}catch(IllegalArgumentException expected){}try{new CreatorSession.Request("n","","","",10);fail();}catch(IllegalArgumentException expected){}try{new CreatorSession.Request("a\nb","rock","","",1);fail();}catch(IllegalArgumentException expected){}assertEquals(1,new CreatorSession.Request("a","","Artist","",1).count);assertEquals(1,new CreatorSession.Request("a","","","mood",1).count);}
 @Test public void previewDoesNotWriteAndDeduplicates()throws Exception{Backend b=new Backend();b.tracks=Arrays.asList(t(1),t(1),null,t(2),t(3));CreatorSession s=new CreatorSession(b);CreatorSession.Preview p=s.prepare(request(2),m->{});assertEquals(2,p.tracks.size());assertEquals(t(2).uri,p.tracks.get(1).uri);assertEquals(0,b.writes);try{p.tracks.clear();fail();}catch(UnsupportedOperationException expected){}}
 @Test public void notEnoughTracksNeverPretendsCount()throws Exception{Backend b=new Backend();CreatorSession s=new CreatorSession(b);try{s.prepare(request(4),m->{});fail();}catch(IOException expected){assertTrue(expected.getMessage().contains("Only 3"));}assertEquals(0,b.writes);}
 @Test public void removeRequiresNewPreviewAndCreatesExactReviewedList()throws Exception{Backend b=new Backend();CreatorSession s=new CreatorSession(b);CreatorSession.Preview first=s.prepare(request(3),m->{}),next=s.remove(first,t(2).uri);assertEquals(2,next.tracks.size());try{s.create(first);fail();}catch(IOException expected){}CreatorSession.Receipt receipt=s.create(next);assertEquals("SpotEnhancer-Evening",receipt.name);assertEquals(2,receipt.count);assertEquals(t(3).uri,b.written.get(1).uri);assertNotNull(UUID.fromString(b.operation));assertEquals(1,b.writes);try{s.create(next);fail();}catch(IOException expected){}assertEquals(1,b.writes);}
 @Test public void cannotRemoveFinalTrack()throws Exception{CreatorSession s=new CreatorSession(new Backend());CreatorSession.Preview p=s.prepare(request(1),m->{});try{s.remove(p,t(1).uri);fail();}catch(IOException expected){}assertEquals(1,s.create(p).count);}
 @Test public void invalidateRejectsStalePreview()throws Exception{Backend b=new Backend();CreatorSession s=new CreatorSession(b);CreatorSession.Preview p=s.prepare(request(2),m->{});s.invalidate();try{s.create(p);fail();}catch(IOException expected){}assertEquals(0,b.writes);}
 @Test public void cancellationWhileGeneratingCannotPublishPreview()throws Exception{CreatorSession s=new CreatorSession(new Backend());try{s.prepare(request(2),m->s.invalidate());fail();}catch(java.util.concurrent.CancellationException expected){}}
 @Test public void ambiguousWriteIsNotRetried()throws Exception{Backend b=new Backend();b.fail=true;CreatorSession s=new CreatorSession(b);CreatorSession.Preview p=s.prepare(request(2),m->{});try{s.create(p);fail();}catch(IOException expected){}try{s.create(p);fail();}catch(IOException expected){}assertEquals(1,b.writes);}
 @Test public void wrongReceiptIsNotSuccess()throws Exception{Backend b=new Backend();b.wrong=true;CreatorSession s=new CreatorSession(b);try{s.create(s.prepare(request(2),m->{}));fail();}catch(IOException expected){assertTrue(expected.getMessage().contains("not fully confirmed"));}assertEquals(1,b.writes);}
 @Test public void fiveHundredTrackRequestIsComplete()throws Exception{Backend b=new Backend();b.tracks.clear();for(int i=0;i<500;i++)b.tracks.add(t(i));CreatorSession s=new CreatorSession(b);assertEquals(500,s.create(s.prepare(request(500),m->{})).count);}
}
